CREATE EXTENSION IF NOT EXISTS "pgcrypto"; CREATE TABLE IF NOT EXISTS datasets (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::TEXT, user_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', file_paths JSONB NOT NULL DEFAULT '[]', total_tokens INTEGER, train_tokens INTEGER, val_tokens INTEGER, vocab_size INTEGER, tokenizer_path TEXT, stats JSONB NOT NULL DEFAULT '{}', raw_bytes BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS idx_datasets_user ON datasets(user_id); CREATE INDEX IF NOT EXISTS idx_datasets_status ON datasets(status); CREATE TABLE IF NOT EXISTS training_jobs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::TEXT, user_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', model_arch TEXT NOT NULL, dataset_id TEXT REFERENCES datasets(id) ON DELETE SET NULL, config JSONB NOT NULL DEFAULT '{}', current_epoch INTEGER NOT NULL DEFAULT 0, total_epochs INTEGER NOT NULL DEFAULT 3, current_step INTEGER NOT NULL DEFAULT 0, total_steps INTEGER NOT NULL DEFAULT 0, train_loss FLOAT, val_loss FLOAT, lr FLOAT, model_path TEXT, error_msg TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ, finished_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS idx_jobs_user ON training_jobs(user_id); CREATE INDEX IF NOT EXISTS idx_jobs_status ON training_jobs(status); CREATE INDEX IF NOT EXISTS idx_jobs_dataset ON training_jobs(dataset_id); CREATE TABLE IF NOT EXISTS model_registry (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::TEXT, user_id TEXT NOT NULL, name TEXT NOT NULL, arch TEXT NOT NULL, job_id TEXT REFERENCES training_jobs(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'training', params TEXT, model_path TEXT, config JSONB NOT NULL DEFAULT '{}', metrics JSONB NOT NULL DEFAULT '{}', endpoint_url TEXT, api_key TEXT, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deployed_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS idx_models_user ON model_registry(user_id); CREATE INDEX IF NOT EXISTS idx_models_status ON model_registry(status); CREATE OR REPLACE FUNCTION update_updated_at() RETURNS TRIGGER AS $$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $$ LANGUAGE plpgsql; DROP TRIGGER IF EXISTS trg_datasets_updated_at ON datasets; CREATE TRIGGER trg_datasets_updated_at BEFORE UPDATE ON datasets FOR EACH ROW EXECUTE FUNCTION update_updated_at(); DROP TRIGGER IF EXISTS trg_jobs_updated_at ON training_jobs; CREATE TRIGGER trg_jobs_updated_at BEFORE UPDATE ON training_jobs FOR EACH ROW EXECUTE FUNCTION update_updated_at();
